import Foundation

/// The pixel font, emoji icons and speech-bubble parts in `Assets/UI`
/// (`ui.png` + `ui.json`, generated by Tools/generate_sprites.py). This type
/// only does layout; the platform renderer draws the pixels.
public struct PixelFont: Sendable {
    public struct Glyph: Codable, Equatable, Sendable {
        public let x: Int
        public let y: Int
        public let w: Int
    }

    public struct Part: Codable, Equatable, Sendable {
        public let x: Int
        public let y: Int
        public let w: Int?
        public let h: Int?
        public let size: Int?
        public let corner: Int?
    }

    public struct Padding: Codable, Equatable, Sendable {
        public let x: Int
        public let top: Int
        public let bottom: Int
    }

    struct Metrics: Codable {
        let lineHeight: Int
        let letterSpacing: Int
        let glyphs: [String: Glyph]
        let bubble: Part
        let tail: Part
        let padding: Padding
    }

    /// A glyph at a horizontal position in a line of text (pixels).
    public struct Placed: Equatable, Sendable {
        public let glyph: Glyph
        public let x: Int
    }

    public let lineHeight: Int
    public let letterSpacing: Int
    public let glyphs: [String: Glyph]
    public let bubble: Part
    public let tail: Part
    public let padding: Padding

    public init(json: Data) throws {
        let metrics = try JSONDecoder().decode(Metrics.self, from: json)
        lineHeight = metrics.lineHeight
        letterSpacing = metrics.letterSpacing
        glyphs = metrics.glyphs
        bubble = metrics.bubble
        tail = metrics.tail
        padding = metrics.padding
    }

    /// Lays out one line. Characters without a glyph become "?"; emoji
    /// variation selectors (U+FE0F) are ignored.
    public func layout(_ text: String) -> (placed: [Placed], width: Int) {
        var placed: [Placed] = []
        var x = 0
        for character in text {
            let key = String(character).replacingOccurrences(of: "\u{FE0F}", with: "")
            guard let glyph = glyphs[key] ?? glyphs["?"] else { continue }
            if !placed.isEmpty { x += letterSpacing }
            placed.append(Placed(glyph: glyph, x: x))
            x += glyph.w
        }
        return (placed, x)
    }
}
